--- build/native-batch/source/jit.cpp	2026-10-26 01:51:18
+++ build/cached-batch-controller/source/jit.cpp	2026-10-26 09:06:14
@@ -155,15 +155,45 @@
     return n;
 }
 Jit::BatchResult Jit::runBatch(unsigned budget) {
-    if (budget > 64) budget = 64;
+    if (budget > 64) budget=64;
     BatchResult result;
-    const auto before = nativeInstructions;
-    while (result.instructions < budget && !cpu.halted) {
-        auto n = run();
-        ++result.dispatches;
-        result.instructions += n;
-        if (!n || nativeInstructions - before != result.instructions)
-            break; // Any interpreter instruction/replay is a device-poll boundary.
+    const auto before=nativeInstructions;
+    while(result.instructions<budget && !cpu.halted) {
+        Block *b=nullptr;
+        // Enter through run() first. Only a successful native dispatch can
+        // reach this shortcut; interpreter boundaries still return to polling.
+        if(result.dispatches && active && !(cpu.flags&TF) &&
+           !(cpu.interruptBlockedThrough && cpu.instructions<=cpu.interruptBlockedThrough)) {
+            uint64_t key=uint64_t(cpu.s[CS].selector)<<48 | uint64_t(cpu.s[CS].big)<<47 | cpu.ip;
+            auto &entry=fast[(cpu.ip^(cpu.ip>>12)^(cpu.s[CS].selector*31u))&4095];
+            auto *candidate=entry.key==key?entry.block:nullptr;
+            if(candidate && candidate->fn && candidate->executionEpoch==cpu.executionEpoch &&
+               candidate->page<cpu.generation.size() && candidate->generation==cpu.generation[candidate->page] &&
+               candidate->cr0==cpu.cr[0] && candidate->cr3==cpu.cr[3] && candidate->csBase==cpu.s[CS].base &&
+               candidate->a20==cpu.a20 && candidate->vm==bool(cpu.flags&0x20000) &&
+               candidate->watched==bool(cpu.watchWrite) && (!candidate->usesStack || candidate->stack32==cpu.s[SS].big) &&
+               candidate->ram==cpu.mem.data() && candidate->ramSize==cpu.mem.size() && candidate->codeBits==cpu.codeUsed.data()) {
+                auto oldCR2=cpu.cr[2];
+                try {
+                    if(!(cpu.cr[0]&0x80000000u) || instructionPage(cpu)==candidate->page)
+                        if(candidate->generation==cpu.generation[candidate->page]) b=candidate;
+                } catch(...) {cpu.cr[2]=oldCR2;}
+            }
+        }
+        uint32_t n;
+        if(b) {
+            profile::event(profile::Dispatch);profile::event(profile::FastHit);profile::event(profile::NativeCall);
+            ++cacheHits;
+            cpu.nativeFallback=false;
+            n=b->fn(&cpu);
+            cpu.instructions+=n;nativeInstructions+=n;
+            if(cpu.nativeFallback) {
+                profile::event(profile::NativeReplay);
+                cpu.nativeFallback=false;cpu.step();++n;
+            }
+        } else n=run();
+        ++result.dispatches;result.instructions+=n;
+        if(!n || nativeInstructions-before!=result.instructions) break;
     }
     return result;
 }
